// TC-156 | req_ids: REQ-029 | level: api | type: hybrid | model: shopcheck@25673b2
// Creating an order with insufficient stock is refused as conflict
// Generated by the QA spec generator (rung 2) — deterministic assembly; do not hand-edit.

import { test, expect } from '../../../fixtures';

test('TC-156: Creating an order with insufficient stock is refused as conflict', async ({ api, loginAs }) => {
  // reset_state is automatic (harness beforeEach)
  await loginAs('standard_user');
  const products: { id: number; name: string; description: string; price: number; stock: number; is_active: boolean }[] = await (await api.get('/api/products')).json();
  const seededProduct = products[0];  // first active seeded product
  await api.get(`/api/products/${seededProduct.id}`);
  // Expected: current stock recorded
  const products2: { id: number; name: string; description: string; price: number; stock: number; is_active: boolean }[] = await (await api.get('/api/products')).json();
  const boundedStock = products2.find((p) => p.stock >= 1 && p.stock < 10);
  if (!boundedStock) throw new Error('no seeded product with stock in the 1-10 order-quantity range');
  // status expectation from verification step 4 — asserted on this call's own response
  const res = await api.post('/api/orders', { data: { items: [{ product_id: boundedStock.id, quantity: boundedStock.stock + 1 }] } });
  expect(res.status()).toBe(409);
  await api.get(`/api/products/${seededProduct.id}`);
  // (409 is the preceding mutating call's status — asserted there, on its own response)
  // Expected: 409 conflict on creation; stock unchanged
});
